using Microsoft.ML.Data;

namespace ChurnPredictor.Models;

/// <summary>Raw row from customers.csv — Churned is "Yes"/"No" text.</summary>
public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool PredictedLabel { get; set; }

    public float Probability { get; set; }

    public float Score { get; set; }
}

arguments.old_str:
using Microsoft.ML;
using ChurnPredictor.Models;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var mlContext = new MLContext(seed: 0);

var dataPath = Path.Combine(app.Environment.ContentRootPath, "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(
    dataPath, hasHeader: true, separatorChar: ',');

// Map "Yes"/"No" label to boolean, encode Region, combine features, then train
var pipeline = mlContext.Transforms.CustomMapping<RawLabel, MappedLabel>(
        (input, output) => output.Label = input.Label,
        contractName: null)
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    .Append(mlContext.Transforms.Concatenate("Features",
        nameof(CustomerData.Age),
        nameof(CustomerData.Income),
        "RegionEncoded",
        nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());

var model = pipeline.Fit(dataView);
var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);

app.MapGet("/", () => "Churn Predictor API — POST /predict with { age, income, region, purchaseHistory }");

app.MapPost("/predict", (CustomerInput input) =>
{
    var customer = new CustomerData
    {
        Age = input.Age,
        Income = input.Income,
        Region = input.Region,
        PurchaseHistory = input.PurchaseHistory
    };

    var prediction = predictionEngine.Predict(customer);

    return Results.Ok(new
    {
        willChurn = prediction.Churned,
        probability = prediction.Probability,
        score = prediction.Score
    });
});

app.Run();

// Minimal input DTO (no label needed for prediction)
record CustomerInput(float Age, float Income, string Region, float PurchaseHistory);

// Identity mapping — ML.NET already parsed "Yes"/"No" → bool via [ColumnName("Label")]
class RawLabel { [Microsoft.ML.Data.ColumnName("Label")] public bool Label { get; set; } }
class MappedLabel { [Microsoft.ML.Data.ColumnName("Label")] public bool Label { get; set; } }

